INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-20' FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Continuous Transaction Control (CTC)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. RO_CIUS validation rules, API endpoints, and penalty amounts change — confirm current specifications directly on ANAF''s e-Factura portal before building an integration.', 'Romania rolled out RO e-Factura in stages — starting as a voluntary channel, then becoming mandatory transaction type by transaction type. This is the full sequence, past and upcoming.', 'Every invoice is a structured XML file — there''s no PDF or paper equivalent that carries legal weight once you''re in scope.', 'Romania runs a centralised clearance (CTC) model: nothing is legally an invoice until ANAF has validated and sealed it.', 'Before you can send or receive a single invoice, there''s a one-time setup process with the central tax authority.', 'E-Factura doesn''t sit alone — two adjacent Romanian reporting regimes commonly trip up new entrants.' FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'CTC', 'Compliance model');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'UBL 2.1', 'Invoice syntax');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '5 days', 'Submission window');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '10 yrs', 'Archive requirement');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '15%', 'Max non-compliance penalty');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Syntax & standard', '[["Base syntax", "UBL 2.1 (ISO/IEC 19845)"], ["European semantic model", "EN 16931"], ["National extension (CIUS)", "RO_CIUS 1.0.1"], ["Legal basis for CIUS", "MF Order 1366/2021"]]', 'CII XML is technically permitted by the EN 16931 standard, but UBL 2.1 is what ANAF''s platform actually validates in practice — use UBL unless you have a specific reason not to.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Validation pipeline', '[["Step 1", "XSD structural validation"], ["Step 2", "Schematron business rules"], ["Rule count", "~118 RO_CIUS rules"], ["Tax ID check", "Real-time CUI/CIF lookup"]]', 'Invalid or inactive CUI/CIF tax IDs cause immediate rejection — the system cross-references ANAF''s live taxpayer database as part of validation, not just a formatting check.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Key mandatory fields', '[["Invoice type code", "380 (standard), 381 (credit note)"], ["Supplier / buyer ID", "CUI / CIF"], ["VAT rate codes", "19% / 9% / 5%"], ["Special codes", "Reverse charge, simplified invoice"]]', 'Romanian-specific tax category codes are required for reverse-charge and simplified invoice scenarios — generic EN 16931 codes alone won''t pass Schematron validation.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving', '[["Retention period", "10 years"], ["Format to retain", "Original signed XML + ANAF response"], ["Buyer retrieval window", "60 days from SPV"]]', 'Retain both the XML you submitted and ANAF''s signed response/downloadId — the government''s digital seal (not your own signature) is what makes the invoice legally valid.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Platform & API', '[["Platform", "SPV (Spațiul Privat Virtual)"], ["REST API host", "efactura.mfinante.gov.ro"], ["Authentication (human)", "Qualified digital certificate"], ["Authentication (M2M)", "OAuth 2.0"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Clearance workflow', '[["1. Submit", "XML uploaded to ANAF"], ["2. Validate", "Structural + semantic checks"], ["3. Seal", "Ministry of Finance digital signature"], ["4. Reference", "Unique downloadId issued"]]', 'Track submission status through pending → validated → rejected. Build retry/backoff logic — ANAF''s infrastructure has known reliability issues during peak filing periods.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Timing rules', '[["Submission deadline", "5 calendar days from issuance"], ["Buyer download window", "60 days"], ["Late submission", "Compliance violation"]]', 'The 5-day clock starts from the tax point (chargeable event), not the date you get around to generating the XML — automate submission immediately upon issuance rather than batching.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Buyer-side obligations', '[["Registration", "Must also register in SPV"], ["Retrieval", "Poll API for invoices by CUI"], ["Verification", "Confirm valid MoF seal present"]]', 'Buyers aren''t passive recipients — you''re expected to actively retrieve invoices addressed to your CUI and can raise a compliance complaint if a supplier fails to issue correctly.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📊 SAF-T reporting', NULL, NULL, 'Standard Audit File for Tax reporting runs alongside e-Factura, covering broader accounting data beyond individual invoices. It was phased in separately, starting with large taxpayers in 2022 and extending progressively to smaller businesses (ANAF Order 1783/2021).');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🚚 RO e-Transport', NULL, NULL, 'If you ship high-risk goods within Romania, logistics declarations must cross-reference the e-Factura clearance ID (downloadId) before shipping. Treat e-Factura and e-Transport as one connected compliance workflow, not two separate systems.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Penalties', NULL, NULL, 'Late or missing submissions trigger fines of RON 1,000–5,000 for small/medium entities, and non-compliance can be penalised at up to 15% of invoice value — one of the stricter enforcement regimes in the EU.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Obtain a qualified digital certificate', 'Get a qualified electronic signature certificate from an accredited Romanian provider. This is the credential ANAF uses to identify you — budget time for this, as certificate issuance isn''t instant.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register for SPV access', 'Create your Spațiul Privat Virtual (Virtual Private Space) account — ANAF''s secure taxpayer portal — using your digital certificate to authenticate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Submit Form 084', 'File Form 084 to formally activate RO e-Factura access for your CUI/CIF. This is the specific registration step that switches on e-invoicing capability within SPV.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up certificate delegation (if using a service provider)', 'If a third-party platform or accountant submits on your behalf, delegate certificate authority to them per entity. This is commonly the trickiest part of integration — delegations must be configured individually and certificates expire, so track renewal dates.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Connect your ERP or invoicing software', 'Integrate via ANAF''s REST API using OAuth 2.0 for machine-to-machine submission, or use the SPV web interface directly for lower volumes. Test thoroughly — RO_CIUS validation is strict, and invalid CUI/CIF references cause instant rejection.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build monitoring into your pipeline', 'Poll for clearance status (pending/validated/rejected), track the 5-day submission clock per invoice, and maintain retry/backoff logic so invoices are submitted exactly once even if ANAF''s endpoint is temporarily unavailable.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice', 0 FROM countries WHERE name_en = 'Romania';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'ANAF / Ministry of Finance — e-Factura');
